insert into public.markets (id, title, category, q_yes, q_no, traders, resolution_date, audio_summary, transcript, tags, creator_alias) values
(1, 'Will I get a return offer from Jane Street after my summer internship?', 'career', 120, 60, 47, '2025-08-15', 'So I just finished my third week at Jane Street and honestly it''s been a whirlwind. The culture is intense — everyone is absurdly smart and I feel like I''m drinking from a firehose every single day. My manager seems happy with my project progress but I haven''t gotten any explicit feedback yet. The return offer rate is historically around 60% but this year they mentioned headcount is tighter. I have 5 weeks left and I''m trying to figure out whether to start recruiting elsewhere just in case...', '[{"time":"0:00","text":"So I just finished my third week at Jane Street..."},{"time":"0:08","text":"...and honestly it''s been a whirlwind."},{"time":"0:12","text":"The culture is intense — everyone is absurdly smart."},{"time":"0:20","text":"My manager seems happy with my project progress..."},{"time":"0:28","text":"...but I haven''t gotten any explicit feedback yet."},{"time":"0:35","text":"The return offer rate is historically around 60%..."},{"time":"0:42","text":"...but this year headcount is tighter."},{"time":"0:50","text":"I have 5 weeks left and I''m deciding whether to recruit elsewhere."}]'::jsonb, '["internship","finance","quant"]'::jsonb, 'anon_7821'),
(2, 'Will I stick to going to the gym 4x/week for the entire month of July?', 'habits', 40, 90, 31, '2025-07-31', 'Okay so I''ve been saying I''m going to get consistent with the gym for literally two years now. I finally got a membership at the CUC and my goal is four days a week for the whole month of July. I''ve downloaded a tracker app, I have a workout plan, and my roommate is supposed to hold me accountable. The problem is I''ve started strong before and then week two or three just completely falls apart when assignments pile up. But this time I''m putting it on Castlot so there''s actual stakes...', '[{"time":"0:00","text":"Okay so I''ve been saying I''m going to get consistent with the gym..."},{"time":"0:07","text":"...for literally two years now."},{"time":"0:10","text":"I finally got a membership at the CUC."},{"time":"0:15","text":"My goal is four days a week for the whole month of July."},{"time":"0:22","text":"I have a tracker app, a workout plan, and an accountability roommate."},{"time":"0:30","text":"The problem is week two or three always falls apart..."},{"time":"0:38","text":"...when assignments pile up."},{"time":"0:44","text":"This time I''m putting it on Castlot so there''s actual stakes."}]'::jsonb, '["gym","habits","wellness"]'::jsonb, 'anon_3341'),
(3, 'Will I choose the startup offer over Google if I get both?', 'career', 55, 70, 62, '2025-06-30', 'I have a really weird problem — I''m currently holding a Google L4 offer for $280k total comp and I''m in final rounds at a 40-person Series B startup doing AI infrastructure. The startup would be around $160k salary plus equity that could be worth a lot or nothing. I went to CMU specifically to do impactful technical work and I genuinely believe in the startup''s mission. But my parents are immigrants and the stability of Google feels deeply important to them and honestly to part of me too. If I get the startup offer, I don''t know what I''ll do...', '[{"time":"0:00","text":"I have a really weird problem."},{"time":"0:04","text":"I''m holding a Google L4 offer for $280k total comp..."},{"time":"0:10","text":"...and I''m in final rounds at a 40-person Series B startup."},{"time":"0:18","text":"The startup does AI infrastructure — I believe in the mission."},{"time":"0:25","text":"But my parents are immigrants. Stability matters to them."},{"time":"0:32","text":"Google is $280k. Startup is $160k plus equity that could be zero."},{"time":"0:40","text":"If I get the startup offer... I genuinely don''t know what I''ll do."}]'::jsonb, '["career","startup","google","decision"]'::jsonb, 'anon_5509'),
(4, 'Will I switch my major from CS to Business before junior year?', 'academics', 35, 80, 29, '2026-01-15', 'I came into CMU as a CS major but honestly I''ve been enjoying my Tepper electives way more than my coding classes. My GPA in CS is fine but I just don''t feel it anymore. Everyone says switching is career suicide but I keep seeing business majors landing amazing jobs too...', '[{"time":"0:00","text":"I came into CMU as a CS major..."},{"time":"0:07","text":"...but my Tepper electives feel way more alive."},{"time":"0:14","text":"My GPA in CS is fine, I just don''t feel it."},{"time":"0:21","text":"Everyone says switching is career suicide."},{"time":"0:28","text":"But business majors are landing amazing jobs too."},{"time":"0:35","text":"I have until junior year to decide."}]'::jsonb, '["academics","major","decision"]'::jsonb, 'anon_2291'),
(24, 'I''m on the waitlist for a single. Will I get it before the semester ends?', 'academics', 45, 75, 24, '2025-05-10', 'I''ve been on the waitlist for a single room since week two of the semester. My RA said ''movement happens'' but hasn''t told me anything concrete. I''m currently in a triple and I genuinely cannot focus. There are supposedly 3 people ahead of me but two of them might be transferring out...', '[{"time":"0:00","text":"I''ve been on the waitlist for a single since week two."},{"time":"0:07","text":"My RA says ''movement happens'' but nothing concrete."},{"time":"0:13","text":"I''m currently in a triple. I cannot focus."},{"time":"0:20","text":"Three people are ahead of me on the list."},{"time":"0:26","text":"Two of them might be transferring out though."},{"time":"0:33","text":"Semester ends in 9 weeks. Fingers crossed."}]'::jsonb, '["housing","dorm","waitlist"]'::jsonb, 'anon_4421'),
(5, 'My roommate owes me $200 from last month. Will I get it back?', 'relationships', 38, 90, 41, '2025-04-01', 'My roommate borrowed $200 for a concert ticket last month and has been ''forgetting'' to Venmo me back ever since. Every time I bring it up he says he''ll send it tonight and then doesn''t. We have 3 more months living together and I don''t want it to get weird but $200 is $200...', '[{"time":"0:00","text":"My roommate borrowed $200 for a concert ticket."},{"time":"0:07","text":"That was a month ago. He hasn''t Venmo''d me back."},{"time":"0:13","text":"Every time I bring it up — ''I''ll send it tonight.''"},{"time":"0:20","text":"He never sends it tonight."},{"time":"0:26","text":"We have 3 more months living together."},{"time":"0:32","text":"$200 is $200. Do I push harder or let it go?"}]'::jsonb, '["roommate","money","relationships"]'::jsonb, 'anon_8832'),
(6, 'I bombed the first round but they said they''d reconsider. Am I getting the callback?', 'career', 22, 95, 55, '2025-03-15', 'I completely blanked on a dynamic programming question in my first round at a top quant firm. The interviewer was actually nice about it and said the team ''sometimes reconsiders strong candidates from other signals.'' I sent a follow-up thank you note. It''s been 5 days. I don''t know if that was a real thing they said or just a polite exit...', '[{"time":"0:00","text":"I blanked on a DP question in my first round."},{"time":"0:07","text":"Top quant firm. It did not go well."},{"time":"0:13","text":"The interviewer said they ''sometimes reconsider.''"},{"time":"0:20","text":"I don''t know if that was real or just a polite exit."},{"time":"0:27","text":"I sent a follow-up note. It''s been 5 days."},{"time":"0:33","text":"Every email notification gives me anxiety."}]'::jsonb, '["recruiting","internship","callback"]'::jsonb, 'anon_6614'),
(7, 'I applied to 12 internships this recruiting season. Will I have an offer by March 1?', 'career', 70, 50, 38, '2025-03-01', 'I''ve sent out 12 applications this recruiting cycle — mix of big tech, fintech, and a couple startups. Got two first rounds so far, one went well and one was a disaster. March 1st is my personal deadline because after that most programs fill up. My GPA is a 3.6 and I have one previous internship so I think I''m a competitive candidate but recruiting feels completely random...', '[{"time":"0:00","text":"12 applications out this cycle. Big tech, fintech, startups."},{"time":"0:08","text":"Two first rounds so far. One good, one disaster."},{"time":"0:15","text":"March 1st is my personal deadline."},{"time":"0:21","text":"After that most programs are filled."},{"time":"0:27","text":"3.6 GPA, one prior internship — I think I''m competitive."},{"time":"0:34","text":"But recruiting feels completely random."}]'::jsonb, '["internship","recruiting","offer"]'::jsonb, 'anon_1193'),
(8, 'My manager hinted at a return offer. Will it be in writing by Friday?', 'career', 55, 60, 33, '2025-03-07', 'My manager pulled me aside yesterday and said the team ''really wants to bring me back'' and that I should ''expect to hear something soon.'' It''s Wednesday. I''m flying home Sunday and I really wanted to have this in writing before I leave. HR hasn''t reached out yet and my manager has gone a bit quiet since that conversation...', '[{"time":"0:00","text":"My manager said the team ''really wants to bring me back.''"},{"time":"0:08","text":"That was yesterday. It''s Wednesday now."},{"time":"0:13","text":"I fly home Sunday. I want this in writing first."},{"time":"0:20","text":"HR hasn''t reached out yet."},{"time":"0:25","text":"My manager has gone quiet since that conversation."},{"time":"0:32","text":"Do I follow up or wait it out?"}]'::jsonb, '["return-offer","internship","career"]'::jsonb, 'anon_7750'),
(9, 'I haven''t started the final project. Will I submit before the deadline?', 'academics', 75, 40, 67, '2025-04-20', 'The final project is worth 40% of my grade and it''s due in 72 hours. I have not started. I''ve opened the spec document four times and closed it. I have all the pieces in my head I just cannot get myself to sit down and start. I''ve done this before and somehow pulled it off. My roommate says I''m cooked. I think I''m fine...', '[{"time":"0:00","text":"Final project. Worth 40% of my grade."},{"time":"0:05","text":"Due in 72 hours. I have not started."},{"time":"0:10","text":"I''ve opened the spec document four times and closed it."},{"time":"0:17","text":"I have all the pieces in my head though."},{"time":"0:23","text":"I''ve pulled this off before."},{"time":"0:28","text":"My roommate says I''m cooked. I think I''m fine."}]'::jsonb, '["academics","procrastination","deadline"]'::jsonb, 'anon_2267'),
(10, 'I''m going to ask my professor to round my 89.2 to an A. Will they say yes?', 'academics', 28, 88, 49, '2025-05-01', 'I have an 89.2 in orgo and I need an A for my med school GPA. I''ve gone to every office hours, submitted all extra credit, and I genuinely tried my best. The professor seems like a reasonable person and I have a draft email written asking if there''s any flexibility. My pre-med advisor said it''s worth asking. My gut says the answer is no but I have to try...', '[{"time":"0:00","text":"89.2 in orgo. I need an A for med school."},{"time":"0:07","text":"I went to every office hours. Did all extra credit."},{"time":"0:14","text":"The professor seems like a reasonable person."},{"time":"0:20","text":"I have a draft email asking for flexibility."},{"time":"0:26","text":"My pre-med advisor said it''s worth asking."},{"time":"0:32","text":"My gut says no. But I have to try."}]'::jsonb, '["grades","academics","premed"]'::jsonb, 'anon_5538'),
(11, 'I''ve been skipping lecture for 3 weeks. Will I pass the midterm anyway?', 'academics', 60, 65, 72, '2025-03-20', 'Okay so I haven''t been to lecture in 3 weeks. The slides are posted online and I''ve been telling myself I''ll catch up but I haven''t. The midterm is in 4 days. I have the notes from a friend, access to all the recordings, and I''m going to do a full cram session this weekend. I''ve passed harder exams on less. The question is whether I can retain 3 weeks of material in 4 days...', '[{"time":"0:00","text":"I haven''t been to lecture in 3 weeks."},{"time":"0:06","text":"Slides are online. I kept saying I''d catch up."},{"time":"0:12","text":"Midterm is in 4 days."},{"time":"0:17","text":"I have notes from a friend and all the recordings."},{"time":"0:23","text":"Full cram session this weekend."},{"time":"0:28","text":"Can I retain 3 weeks of material in 4 days?"}]'::jsonb, '["academics","midterm","cramming"]'::jsonb, 'anon_9901'),
(12, 'I texted them first last 4 times in a row. Will they text me first this week?', 'relationships', 35, 80, 88, '2025-03-09', 'I''ve initiated every single conversation for the past two weeks. Four texts, all me first, all responded to warmly but never started by them. I told myself I''m not texting first this week just to see what happens. Part of me thinks they''ll reach out by Wednesday. Part of me thinks I''ll hear nothing and have my answer. Either way I''ll know something I didn''t before...', '[{"time":"0:00","text":"I''ve texted first four times in a row."},{"time":"0:06","text":"They always respond warmly. Never initiate."},{"time":"0:12","text":"This week I''m not texting first."},{"time":"0:17","text":"Part of me thinks they''ll reach out by Wednesday."},{"time":"0:23","text":"Part of me thinks I''ll hear nothing."},{"time":"0:29","text":"Either way I''ll know something I didn''t before."}]'::jsonb, '["relationships","texting","situationship"]'::jsonb, 'anon_3384'),
(13, 'We''ve been talking for 2 months. Will we make it official before spring break?', 'relationships', 52, 65, 94, '2025-03-22', 'We''ve been in this undefined talking stage for exactly two months now. We hang out multiple times a week, I''ve met some of their friends, and there''s clearly something real here. Spring break is in 3 weeks and I feel like that trip apart is going to either make things click or let them fizzle. I want to have a conversation before we leave but I''m scared of ruining what we have...', '[{"time":"0:00","text":"Two months in the talking stage. Undefined."},{"time":"0:07","text":"We hang out multiple times a week."},{"time":"0:12","text":"I''ve met some of their friends. This is real."},{"time":"0:18","text":"Spring break is in 3 weeks."},{"time":"0:23","text":"Time apart will either make it click or fizzle."},{"time":"0:29","text":"I want to have the talk. I''m scared to ruin it."}]'::jsonb, '["relationships","official","talking-stage"]'::jsonb, 'anon_6621'),
(14, 'My long-distance best friend and I are planning a visit. Will it actually happen?', 'relationships', 48, 70, 31, '2025-03-30', 'My best friend from home and I have been trying to plan a visit since September. We''ve picked three different weekends and something has come up every single time — their work schedule, my midterms, a family thing. We have a new date set for late March and we''re both really committed this time. But we''ve said that before...', '[{"time":"0:00","text":"My best friend and I have been planning a visit since September."},{"time":"0:08","text":"Three different weekends. Something came up every time."},{"time":"0:15","text":"Work schedules, midterms, family stuff."},{"time":"0:21","text":"New date set for late March."},{"time":"0:26","text":"We''re both really committed this time."},{"time":"0:31","text":"But we''ve said that before."}]'::jsonb, '["friendship","long-distance","plans"]'::jsonb, 'anon_4410'),
(15, 'I said I''d stop ordering DoorDash for a month. Will I make it?', 'purchases', 25, 95, 61, '2025-04-10', 'I spent $340 on DoorDash last month. I saw the number and was genuinely shocked. I told my roommates I''m going cold turkey for 30 days starting Monday. They think I''ll last a week. I''ve meal prepped before and it always collapses around day 10 when I have a bad day and just need pad thai delivered at 11pm. But this time I''m serious. Probably...', '[{"time":"0:00","text":"I spent $340 on DoorDash last month."},{"time":"0:06","text":"I saw the number and was genuinely shocked."},{"time":"0:11","text":"Cold turkey for 30 days starting Monday."},{"time":"0:17","text":"My roommates think I''ll last a week."},{"time":"0:22","text":"It always collapses around day 10. Bad day, late night pad thai."},{"time":"0:30","text":"This time I''m serious. Probably."}]'::jsonb, '["money","doordash","habits"]'::jsonb, 'anon_7723'),
(16, 'I''m trying to sell my textbooks before the semester ends. Will I find a buyer?', 'purchases', 55, 60, 22, '2025-05-10', 'I have four textbooks I need to sell before I move out. Listed them on the CMU Facebook group two weeks ago and got zero responses. They''re not rare books — intro econ, calc 2, a stats textbook, and one programming book. I lowered the price once already. The semester ends in 6 weeks and after that I''ll have to either ship them or trash them...', '[{"time":"0:00","text":"Four textbooks I need to sell before move-out."},{"time":"0:07","text":"Listed on the CMU Facebook group. Zero responses."},{"time":"0:13","text":"Intro econ, calc 2, stats, a programming book."},{"time":"0:19","text":"I lowered the price once already."},{"time":"0:25","text":"Six weeks left. After that I have to ship or trash them."},{"time":"0:31","text":"Is anyone even buying textbooks anymore?"}]'::jsonb, '["textbooks","money","selling"]'::jsonb, 'anon_8812'),
(17, 'I committed to not buying anything on Amazon for 30 days. Do I make it?', 'purchases', 30, 88, 44, '2025-04-15', 'I''ve ordered something on Amazon literally every week for the past 4 months. I looked at my purchase history and I''m spending around $200 a month on random stuff I don''t need. I''m doing a 30-day no-Amazon challenge starting today. I''ve already thought of three things I ''need'' that I won''t be able to buy. This is going to be harder than I thought...', '[{"time":"0:00","text":"I''ve ordered on Amazon every week for 4 months."},{"time":"0:07","text":"$200 a month on stuff I don''t need."},{"time":"0:12","text":"30-day no-Amazon challenge starting today."},{"time":"0:18","text":"I''ve already thought of three things I ''need.''"},{"time":"0:24","text":"The urge is already there and it''s day one."},{"time":"0:29","text":"This is going to be harder than I thought."}]'::jsonb, '["amazon","spending","challenge"]'::jsonb, 'anon_3301'),
(18, 'I signed up for a 5K in 6 weeks. Will I actually run it?', 'habits', 62, 55, 37, '2025-04-27', 'I signed up for a 5K that''s happening in 6 weeks. I have not run since high school. I was motivated when I registered but I haven''t actually started training yet and it''s been 10 days. The registration was $35 which I''m hoping is enough to keep me accountable. My friend who talked me into it runs a 22-minute 5K. I would be happy to finish...', '[{"time":"0:00","text":"Signed up for a 5K. It''s in 6 weeks."},{"time":"0:06","text":"I have not run since high school."},{"time":"0:11","text":"10 days since I registered. Still haven''t started training."},{"time":"0:18","text":"Registration was $35. That''s my accountability."},{"time":"0:24","text":"My friend runs a 22-minute 5K."},{"time":"0:29","text":"I would be happy to finish. Just finish."}]'::jsonb, '["fitness","5k","habits"]'::jsonb, 'anon_5529'),
(19, 'I''ve been meaning to make a therapy appointment for 2 months. Will I book it this week?', 'habits', 45, 68, 53, '2025-03-09', 'I''ve been telling myself I need to make a therapy appointment since the start of the semester. I have insurance that covers it, I''ve done therapy before and it helped, and I know the number to call. I just keep not doing it. Every Sunday I say I''ll do it Monday. It''s been 8 Sundays. Something about actually making the call feels harder than it should...', '[{"time":"0:00","text":"I''ve been meaning to book therapy since the semester started."},{"time":"0:08","text":"I have insurance. I''ve done it before and it helped."},{"time":"0:15","text":"I know the number to call. I just keep not doing it."},{"time":"0:22","text":"Every Sunday I say I''ll do it Monday."},{"time":"0:28","text":"It''s been 8 Sundays."},{"time":"0:33","text":"Making the call feels harder than it should."}]'::jsonb, '["mentalhealth","therapy","habits"]'::jsonb, 'anon_1128'),
(20, 'I told my friends I''m cutting out alcohol for January. Do I make it the full month?', 'habits', 42, 75, 66, '2025-02-01', 'I announced to my friend group that I''m doing dry January. I''m 11 days in and it''s been fine so far — mostly because nothing major has happened yet. This weekend is a birthday party and next weekend is a formal. Those are the real tests. I''ve never done a full dry month before. My friends are betting against me. I want to prove them wrong...', '[{"time":"0:00","text":"Dry January. Day 11. Fine so far."},{"time":"0:06","text":"Nothing major has happened yet. That''s the key."},{"time":"0:12","text":"This weekend: birthday party."},{"time":"0:16","text":"Next weekend: formal."},{"time":"0:20","text":"Those are the real tests."},{"time":"0:25","text":"My friends are betting against me. I want to prove them wrong."}]'::jsonb, '["dryjanuary","habits","alcohol"]'::jsonb, 'anon_9934'),
(21, 'I said I''d join a club this semester. Will I actually go to a meeting?', 'academics', 55, 60, 29, '2025-03-13', 'I''ve been saying I''ll join a club since freshman year. I''m a junior now. Every Activities Fair I sign up for 6 mailing lists and attend zero meetings. This semester I picked one club — just one — that I actually care about. Their next meeting is Thursday. I have it in my calendar. I have no excuse. But I also had it in my calendar last semester...', '[{"time":"0:00","text":"I''ve said I''d join a club since freshman year."},{"time":"0:06","text":"I''m a junior. Zero meetings attended."},{"time":"0:11","text":"This semester I picked one club I actually care about."},{"time":"0:18","text":"Next meeting is Thursday. It''s in my calendar."},{"time":"0:24","text":"I have no excuse this time."},{"time":"0:29","text":"But I also had it in my calendar last semester."}]'::jsonb, '["clubs","campus","sociallife"]'::jsonb, 'anon_4477'),
(22, 'My friend group has been trying to plan a trip for months. Does it actually happen?', 'relationships', 40, 80, 58, '2025-03-22', 'Six of us have been in a group chat called ''TRIP 2025'' since October. We''ve narrowed it down to two destinations, had three Google Meet calls, and made zero bookings. Every time we get close someone has a conflict or a budget concern. I love these people but group trip planning is a nightmare. Spring break is the target. I give us 40/60 odds...', '[{"time":"0:00","text":"Group chat called ''TRIP 2025'' since October."},{"time":"0:07","text":"Six people. Three planning calls. Zero bookings."},{"time":"0:13","text":"Two destinations narrowed down. Still no decision."},{"time":"0:20","text":"Every time we get close someone has a conflict."},{"time":"0:27","text":"Spring break is the target."},{"time":"0:31","text":"I give us 40/60 odds. Maybe."}]'::jsonb, '["grouptrip","friends","planning"]'::jsonb, 'anon_6650'),
(23, 'I have a presentation in front of 80 people next week. Will I wing it or actually practice?', 'academics', 48, 70, 45, '2025-03-14', 'I have a 10-minute presentation for my capstone class next Friday. There are 80 people in the room including professors and recruiters. I have the slides done but I haven''t practiced out loud once. Every night this week I''ve told myself I''ll run through it tomorrow. It''s Wednesday. I''m a good improviser but this one actually matters and I know I should practice. Will I?', '[{"time":"0:00","text":"10-minute capstone presentation next Friday."},{"time":"0:07","text":"80 people. Professors and recruiters in the room."},{"time":"0:13","text":"Slides are done. Zero practice out loud."},{"time":"0:19","text":"Every night this week: ''I''ll practice tomorrow.''"},{"time":"0:25","text":"It''s Wednesday. This one actually matters."},{"time":"0:31","text":"I''m a good improviser. But will I practice?"}]'::jsonb, '["presentation","academics","publicspeaking"]'::jsonb, 'anon_2255');
